class T:
    """Design tokens.  The palette is built from signal aspects - red, amber
    and green are never decorative here, they always carry state."""

    INK = "#0B1220"        # header / mast
    PANEL = "#131C2E"      # raised dark panel
    PANEL_2 = "#1B2740"    # dark panel hover
    BG = "#EEF1F6"         # page background
    CARD = "#FFFFFF"
    CARD_EDGE = "#D5DCE7"
    CARD_EDGE_HOT = "#2F6BFF"

    TEXT = "#0B1220"
    TEXT_SOFT = "#5A6B85"
    TEXT_INV = "#FFFFFF"
    TEXT_MUTE = "#8FA0BC"

    BLUE = "#2F6BFF"
    BLUE_HOT = "#1B54E0"
    VIOLET = "#7C4DEF"
    VIOLET_HOT = "#6A3BDD"

    RED = "#E1443B"        # aspect RED  - stopped / failed
    AMBER = "#F2B23A"      # aspect AMBER - running / waiting
    GREEN = "#22A45D"      # aspect GREEN - complete / ready
    GREY = "#7C8AA0"       # lamp off

    SLATE = "#334155"

    @staticmethod
    def f(size, weight="normal"):
        return ("Segoe UI", size, weight)

    @staticmethod
    def mono(size, weight="normal"):
        return ("Consolas", size, weight)


