def rounded(canvas, x1, y1, x2, y2, r, **kw):
    """Draws a rounded rectangle as a smoothed polygon."""

    r = min(r, abs(x2 - x1) / 2, abs(y2 - y1) / 2)

    pts = [
        x1 + r, y1, x2 - r, y1, x2, y1, x2, y1 + r,
        x2, y2 - r, x2, y2, x2 - r, y2, x1 + r, y2,
        x1, y2, x1, y2 - r, x1, y1 + r, x1, y1,
    ]

    return canvas.create_polygon(pts, smooth=True, **kw)


class RButton(tk.Canvas):
    """Flat rounded button with a hover state.  Pure tkinter, no images."""

    def __init__(self, parent, text, command=None, w=230, h=46,
                 face=T.BLUE, face_hot=None, fg=T.TEXT_INV,
                 font=None, radius=10, edge="", bg=None):

        bg = bg if bg is not None else _bg_of(parent)

        super().__init__(parent, width=w, height=h, bg=bg,
                         highlightthickness=0, bd=0)

        self.command = command
        self.face = face
        self.face_hot = face_hot or _shade(face, -0.14)
        self.enabled = True

        # NOTE: never store width as self._w - tkinter uses that attribute
        # internally for the widget path name.
        self.btn_w, self.btn_h = w, h

        self.shape = rounded(self, 1, 1, w - 1, h - 1, radius,
                             fill=face, outline=edge or face)

        self.label = self.create_text(w / 2, h / 2, text=text, fill=fg,
                                      font=font or T.f(11, "bold"))

        self.configure(cursor="hand2")

        self.bind("<Enter>", self._enter)
        self.bind("<Leave>", self._leave)
        self.bind("<Button-1>", self._press)
        self.bind("<ButtonRelease-1>", self._release)

    # -- state -------------------------------------------------------------

    def set_text(self, text):
        self.itemconfig(self.label, text=text)

    def set_face(self, face):
        self.face = face
        self.face_hot = _shade(face, -0.14)
        self.itemconfig(self.shape, fill=face, outline=face)

    def set_enabled(self, flag):
        self.enabled = flag
        if flag:
            self.itemconfig(self.shape, fill=self.face, outline=self.face)
            self.itemconfig(self.label, fill=T.TEXT_INV)
            self.configure(cursor="hand2")
        else:
            self.itemconfig(self.shape, fill="#C3CBD8", outline="#C3CBD8")
            self.itemconfig(self.label, fill="#EFF2F7")
            self.configure(cursor="arrow")

    # -- events ------------------------------------------------------------

    def _enter(self, _=None):
        if self.enabled:
            self.itemconfig(self.shape, fill=self.face_hot,
                            outline=self.face_hot)

    def _leave(self, _=None):
        if self.enabled:
            self.itemconfig(self.shape, fill=self.face, outline=self.face)

    def _press(self, _=None):
        if self.enabled:
            self.move(self.label, 0, 1)

    def _release(self, _=None):
        if not self.enabled:
            return
        self.move(self.label, 0, -1)
        if self.command:
            self.command()


class GhostButton(RButton):
    """Outlined button for secondary actions such as BACK."""

    def __init__(self, parent, text, command=None, w=150, h=46,
                 colour=T.SLATE, **kw):

        bg = _bg_of(parent)

        super().__init__(parent, text, command, w=w, h=h,
                         face=bg, fg=colour, edge=colour, bg=bg, **kw)

        self.itemconfig(self.shape, fill=bg, outline=colour, width=1)
        self.base_bg = bg
        self.colour = colour

    def _enter(self, _=None):
        if self.enabled:
            self.itemconfig(self.shape, fill="#E2E8F1", outline=self.colour)

    def _leave(self, _=None):
        if self.enabled:
            self.itemconfig(self.shape, fill=self.base_bg,
                            outline=self.colour)


class Lamp(tk.Canvas):
    """A signal aspect lamp.  Used for step progress and program status."""

    def __init__(self, parent, d=16, colour=T.GREY, bg=None, glow=True):

        bg = bg if bg is not None else _bg_of(parent)
        pad = 4 if glow else 1
        size = d + pad * 2

        super().__init__(parent, width=size, height=size, bg=bg,
                         highlightthickness=0, bd=0)

        self.glow_id = self.create_oval(1, 1, size - 1, size - 1,
                                        fill=bg, outline=bg) if glow else None

        self.bulb = self.create_oval(pad, pad, pad + d, pad + d,
                                     fill=colour, outline=_shade(colour, -0.2))

        self.bg = bg
        self.set(colour)

    def set(self, colour, lit=True):
        self.itemconfig(self.bulb, fill=colour,
                        outline=_shade(colour, -0.25))
        if self.glow_id is not None:
            halo = _mix(colour, self.bg, 0.72) if lit else self.bg
            self.itemconfig(self.glow_id, fill=halo, outline=halo)


class Toggle(tk.Canvas):
    """A compact on/off pill switch."""

    def __init__(self, parent, value=True, command=None, bg=None):

        bg = bg if bg is not None else _bg_of(parent)
        self.w, self.h = 52, 26

        super().__init__(parent, width=self.w, height=self.h, bg=bg,
                         highlightthickness=0, bd=0)

        self.value = value
        self.command = command

        self.track = rounded(self, 1, 1, self.w - 1, self.h - 1, 12,
                             fill=T.GREEN, outline=T.GREEN)

        self.knob = self.create_oval(0, 0, 0, 0, fill="white",
                                    outline="#E2E8F1")

        self.configure(cursor="hand2")
        self.bind("<Button-1>", self._flip)

        self._draw()

    def _draw(self):

        if self.value:
            self.itemconfig(self.track, fill=T.GREEN, outline=T.GREEN)
            x = self.w - self.h + 3
        else:
            self.itemconfig(self.track, fill="#B9C4D4", outline="#B9C4D4")
            x = 3

        self.coords(self.knob, x, 3, x + self.h - 6, self.h - 3)

    def _flip(self, _=None):
        self.value = not self.value
        self._draw()
        if self.command:
            self.command(self.value)

    def set(self, value):
        self.value = value
        self._draw()


class CheckMark(tk.Canvas):
    """Square tick box with an order badge for the run sequence."""

    SIZE = 30

    def __init__(self, parent, bg=None):

        bg = bg if bg is not None else _bg_of(parent)
        s = self.SIZE

        super().__init__(parent, width=s, height=s, bg=bg,
                         highlightthickness=0, bd=0)

        self.box = rounded(self, 2, 2, s - 2, s - 2, 8,
                           fill="#FFFFFF", outline="#B9C4D4")

        self.tick = self.create_text(s / 2, s / 2 - 1, text="",
                                     fill=T.TEXT_INV, font=T.f(12, "bold"))

    def set(self, checked, order=None):
        if checked:
            self.itemconfig(self.box, fill=T.BLUE, outline=T.BLUE)
            self.itemconfig(self.tick, text=str(order) if order else "OK")
        else:
            self.itemconfig(self.box, fill="#FFFFFF", outline="#B9C4D4")
            self.itemconfig(self.tick, text="")


# --------------------------------------------------------------- helpers -----

def _bg_of(widget):
    try:
        return widget.cget("bg")
    except Exception:
        return T.BG


def _hex_to_rgb(h):
    h = h.lstrip("#")
    return tuple(int(h[i:i + 2], 16) for i in (0, 2, 4))


def _rgb_to_hex(rgb):
    return "#%02x%02x%02x" % tuple(max(0, min(255, int(c))) for c in rgb)


def _shade(colour, amount):
    """amount < 0 darkens, amount > 0 lightens."""

    r, g, b = _hex_to_rgb(colour)

    if amount < 0:
        f = 1 + amount
        return _rgb_to_hex((r * f, g * f, b * f))

    return _rgb_to_hex((r + (255 - r) * amount,
                        g + (255 - g) * amount,
                        b + (255 - b) * amount))


def _mix(a, b, t):
    """t = 0 -> a,  t = 1 -> b"""

    ra, ga, ba = _hex_to_rgb(a)
    rb, gb, bb = _hex_to_rgb(b)

    return _rgb_to_hex((ra + (rb - ra) * t,
                        ga + (gb - ga) * t,
                        ba + (bb - ba) * t))


def card(parent, **kw):
    """A white panel with a hairline border."""

    return tk.Frame(parent, bg=T.CARD, highlightbackground=T.CARD_EDGE,
                    highlightthickness=1, bd=0, **kw)


def short_path(p, limit=58):
    p = str(p)
    return p if len(p) <= limit else "..." + p[-(limit - 3):]


