class SuiteApp(tk.Tk):

    STEPS = ["OEM", "DATA", "PROGRAMS", "EXECUTION"]

    def __init__(self):

        super().__init__()

        self.title("EDRC RAILWAY SIGNAL AUTOMATION SUITE")
        self.geometry("1480x940")
        self.configure(bg=T.BG)
        self.minsize(1180, 760)

        try:
            self.state("zoomed")
        except Exception:
            pass

        # ---- session state ----
        self.oem = None
        self.files = {slot["key"]: None for slot in DATA_SLOTS}
        # Separate Excel list used by the Visual Inspection track-coordinate
        # capture workflow.  It is intentionally kept separate from the saved
        # TRACK_COORDS workbook.
        self.track_list_path = None
        self.track_capture_proc = None
        self.selected = []            # program keys, in tick order
        self.step = 0

        self.unattended = True        # walk-away: auto Load + Start + close

        self.running = False
        self.proc = None
        self.session_dir = None
        self.results = {}
        self.claimed = set()

        self.ui_queue = queue.Queue()

        self.script_override = self._load_suite_config()

        # ---- layout ----
        self._build_header()
        self._build_body()
        self._build_footer()

        self.pages = {}
        self.page_oem = PageOEM(self.body, self)
        self.page_data = PageData(self.body, self)
        self.page_prog = PagePrograms(self.body, self)
        self.page_run = PageRun(self.body, self)

        for pg in (self.page_oem, self.page_data, self.page_prog, self.page_run):
            pg.place(x=0, y=0, relwidth=1, relheight=1)

        self.show_step(0)

        self.protocol("WM_DELETE_WINDOW", self.on_close)

        self._pump()

    # =====================================================================
    #  CHROME
    # =====================================================================

    def _build_header(self):

        head = tk.Frame(self, bg=T.INK, height=104)
        head.pack(fill="x")
        head.pack_propagate(False)

        left = tk.Frame(head, bg=T.INK)
        left.pack(side="left", padx=(24, 0))

        self._logo(left, IR_LOGO, (74, 74), "INDIAN RAILWAYS")

        title = tk.Frame(head, bg=T.INK)
        title.pack(side="left", padx=24)

        tk.Label(title, text="R A I L W A Y   S I G N A L   T E S T I N G",
                 bg=T.INK, fg=T.AMBER, font=T.f(9, "bold")
                 ).pack(anchor="w", pady=(24, 0))

        tk.Label(title, text="EDRC AUTOMATION SUITE",
                 bg=T.INK, fg=T.TEXT_INV, font=T.f(25, "bold")
                 ).pack(anchor="w")

        # OEM badge sits on the right of the title, filled once chosen.
        self.oem_badge = tk.Label(head, text="", bg=T.INK, fg=T.TEXT_MUTE,
                                  font=T.f(11, "bold"))
        self.oem_badge.pack(side="left", padx=10)

        right = tk.Frame(head, bg=T.INK)
        right.pack(side="right", padx=(0, 24))

        self._logo(right, COMPANY_LOGO, (120, 120), "EDRC TEAM")

    def _logo(self, parent, path, size, fallback):

        if PIL_OK and Path(path).exists():
            try:
                img = Image.open(path)
                img.thumbnail(size, Image.Resampling.LANCZOS)
                photo = ImageTk.PhotoImage(img)
                lab = tk.Label(parent, image=photo, bg=T.INK)
                lab.image = photo
                lab.pack(pady=8)
                return
            except Exception:
                pass

        tk.Label(parent, text=fallback, bg=T.INK, fg=T.TEXT_INV,
                 font=T.f(10, "bold")).pack(pady=30)

    def _build_body(self):

        shell = tk.Frame(self, bg=T.BG)
        shell.pack(fill="both", expand=True)

        # ---- signal mast : the step indicator ----
        mast = tk.Frame(shell, bg=T.INK, width=210)
        mast.pack(side="left", fill="y")
        mast.pack_propagate(False)

        tk.Label(mast, text="S E Q U E N C E", bg=T.INK, fg=T.TEXT_MUTE,
                 font=T.f(9, "bold")).pack(anchor="w", padx=22, pady=(26, 16))

        self.step_rows = []

        for i, name in enumerate(self.STEPS):

            row = tk.Frame(mast, bg=T.INK)
            row.pack(fill="x", padx=18, pady=7)

            lamp = Lamp(row, d=15, colour=T.GREY, bg=T.INK)
            lamp.pack(side="left")

            txt = tk.Frame(row, bg=T.INK)
            txt.pack(side="left", padx=10)

            num = tk.Label(txt, text="STEP %d" % (i + 1), bg=T.INK,
                           fg=T.TEXT_MUTE, font=T.f(8, "bold"))
            num.pack(anchor="w")

            lab = tk.Label(txt, text=name, bg=T.INK, fg=T.TEXT_MUTE,
                           font=T.f(12, "bold"))
            lab.pack(anchor="w")

            self.step_rows.append((lamp, lab, num))

            if i < len(self.STEPS) - 1:
                tk.Frame(mast, bg="#22304A", height=1).pack(
                    fill="x", padx=(26, 40))

        tk.Frame(mast, bg=T.INK).pack(fill="both", expand=True)

        self.mast_hint = tk.Label(
            mast, text="", bg=T.INK, fg=T.TEXT_MUTE,
            font=T.f(9), justify="left", wraplength=170)
        self.mast_hint.pack(anchor="w", padx=22, pady=22)

        self.body = tk.Frame(shell, bg=T.BG)
        self.body.pack(side="left", fill="both", expand=True)

    def _build_footer(self):

        foot = tk.Frame(self, bg=T.INK, height=34)
        foot.pack(fill="x")
        foot.pack_propagate(False)

        self.foot_label = tk.Label(
            foot,
            text="READY  -  SELECT AN OEM TO BEGIN",
            bg=T.INK, fg=T.TEXT_MUTE, font=T.f(9, "bold"))
        self.foot_label.pack(side="left", padx=22)

        tk.Label(foot, text="EDRC TEAM  |  ONE PROGRAM AT A TIME  |  "
                            "ONE REPORT PER PROGRAM",
                 bg=T.INK, fg="#42536E", font=T.f(9)).pack(side="right",
                                                           padx=22)

    # =====================================================================
    #  NAVIGATION
    # =====================================================================

    def show_step(self, index):

        self.step = index

        pages = [self.page_oem, self.page_data, self.page_prog, self.page_run]
        pages[index].tkraise()
        pages[index].on_show()

        hints = [
            "Pick the interlocking supplier for this yard.",
            "Load the data files once. Every program in the run uses them.",
            "Tick order is run order.",
            "Do not touch the yard terminal while a program is running.",
        ]

        self.mast_hint.config(text=hints[index])

        for i, (lamp, lab, num) in enumerate(self.step_rows):

            if i < index:
                lamp.set(T.GREEN)
                lab.config(fg="#C7D3E6")
                num.config(fg="#4C6084")
            elif i == index:
                lamp.set(T.AMBER)
                lab.config(fg=T.TEXT_INV)
                num.config(fg=T.AMBER)
            else:
                lamp.set(T.GREY, lit=False)
                lab.config(fg=T.TEXT_MUTE)
                num.config(fg="#3A4A66")

    def set_footer(self, text, colour=T.TEXT_MUTE):
        self.foot_label.config(text=text, fg=colour)

    # =====================================================================
    #  DATA FILES
    # =====================================================================

    def pick_file(self, key, label):

        path = filedialog.askopenfilename(
            title=label,
            filetypes=[("Excel Files", "*.xlsx *.xlsm *.xls"),
                       ("All Files", "*.*")])

        if not path:
            return

        self.files[key] = path
        self.page_data.refresh()
        self.set_footer("LOADED  %s  ->  %s" % (key, Path(path).name), T.GREEN)

    def clear_file(self, key):
        self.files[key] = None
        self.page_data.refresh()

    def pick_track_list(self):
        """Select the Excel track list used by Visual Inspection capture."""
        path = filedialog.askopenfilename(
            title="Select Track List Excel",
            filetypes=[("Excel Files", "*.xlsx *.xlsm *.xls"),
                       ("All Files", "*.*")])
        if not path:
            return

        self.track_list_path = path
        self.page_data.refresh()
        self.set_footer("TRACK LIST  ->  %s" % Path(path).name, T.GREEN)

    def start_track_capture(self):
        """Open the existing Visual Inspection track-capture workflow.

        The selected track list is fed into import_track_list(), and the
        existing start_track_capture() function creates the familiar capture
        overlay.  No capture logic is duplicated in the master console.
        """
        if self.running:
            messagebox.showwarning(
                "TRACK CAPTURE",
                "A program queue is currently running. Stop it before starting track capture."
            )
            return

        if not self.track_list_path or not Path(self.track_list_path).exists():
            messagebox.showwarning(
                "TRACK CAPTURE",
                "Please click 'TRACK LIST' first and select the Excel track list."
            )
            return

        # If an existing workbook has been selected, capture updates it.
        # Otherwise create the normal saved workbook beside the track list.
        track_coords = self.files.get("TRACK_COORDS")
        if not track_coords:
            track_coords = str(
                Path(self.track_list_path).with_name("TRACK_COORDINATES_CAPTURED.xlsx")
            )
            self.files["TRACK_COORDS"] = track_coords

        # IMPORTANT: TRACK CAPTURE is a standalone capture action.
        # Do NOT launch visual_inspection_tracks.py here because that opens
        # the full Visual Inspection dashboard.  The direct helper below
        # contains only the existing track-list -> mouse coordinate capture
        # workflow and opens the small capture overlay immediately.
        helper = SCRIPT_DIR / "_edrc_direct_track_capture.py"
        try:
            helper.write_text(DIRECT_TRACK_CAPTURE_SOURCE, encoding="utf-8")

            env = os.environ.copy()
            env["EDRC_TRACK_LIST"] = str(self.track_list_path)
            env["EDRC_TRACK_COORDS"] = str(track_coords)

            self.track_capture_proc = subprocess.Popen(
                [sys.executable, str(helper)],
                cwd=str(SCRIPT_DIR),
                env=env
            )
            self.page_data.refresh()
            self.set_footer(
                "TRACK CAPTURE OPEN  ->  %s" % Path(track_coords).name,
                T.VIOLET
            )
        except Exception as exc:
            messagebox.showerror(
                "TRACK CAPTURE",
                "Could not start direct track capture.\n\n%s" % exc
            )

    def _find_recorder(self):
        """Locates the Universal Yard Coordinate Recorder.  Looks, in order:
        a remembered path, then next to the launcher, then in the same
        folder(s) as the attached test programs (so it's found even when the
        programs live elsewhere, e.g. Desktop\\AFAT FINAL).  Falls back to a
        loose name match so a slightly different file name still works."""

        # 1. remembered choice
        saved = self.script_override.get("RECORDER")
        if saved and Path(saved).exists():
            return saved

        # 2. build the list of folders to search
        search_dirs = [SCRIPT_DIR]

        for prog in PROGRAMS:
            sp = self.script_path(prog)
            if sp:
                search_dirs.append(sp.parent)

        for k, p in self.script_override.items():
            if k != "RECORDER" and p:
                search_dirs.append(Path(p).parent)

        # de-duplicate while preserving order
        seen = set()
        folders = []
        for d in search_dirs:
            d = Path(d)
            key = str(d).lower()
            if key not in seen and d.exists():
                seen.add(key)
                folders.append(d)

        # 3. exact known names first
        for d in folders:
            for name in RECORDER_CANDIDATES:
                cand = d / name
                if cand.exists():
                    return str(cand)

        # 4. loose match - any file that looks like the recorder
        patterns = ["*coordinate*recorder*.py", "*yard*coordinate*.py",
                    "*universal*yard*.py", "*recorder*.py"]
        for d in folders:
            for pat in patterns:
                for cand in sorted(d.glob(pat)):
                    return str(cand)

        return None

    def record_new_coordinates(self):
        """LOAD COORDINATES > NEW  -  opens the Universal Yard Coordinate
        Recorder so a fresh coordinate workbook can be captured.  The recorder
        is a normal interactive tool, so it is launched directly - never
        through the walk-away helper."""

        script = self._find_recorder()

        if not script:

            messagebox.showinfo(
                "Locate the recorder",
                "Could not find universal_yard_coordinate_recorder.py next to "
                "the launcher or beside your programs.\n\nSelect it now - the "
                "location is remembered for next time.")

            script = filedialog.askopenfilename(
                title="Select universal_yard_coordinate_recorder.py",
                filetypes=[("Python", "*.py"), ("All Files", "*.*")])

            if not script:
                return

        self.script_override["RECORDER"] = script
        self._save_suite_config()

        self.set_footer("RECORDER OPEN  -  capture the yard, Export the "
                        "workbook, then use EXISTING to load it", T.AMBER)

        try:
            # Launch from the recorder's own folder, plainly (not via the
            # auto-run helper) so it behaves like opening it in PyCharm.
            subprocess.Popen([sys.executable, script],
                             cwd=str(Path(script).parent))
        except Exception as exc:
            messagebox.showerror("Recorder",
                                 "Could not start the recorder.\n\n%s" % exc)

    # =====================================================================
    #  PROGRAM SELECTION
    # =====================================================================

    def toggle_program(self, key):

        if self.running:
            return

        if key in self.selected:
            self.selected.remove(key)
        else:
            self.selected.append(key)

        self.page_prog.refresh()

    def clear_selection(self):
        self.selected = []
        self.page_prog.refresh()

    def select_all(self):
        self.selected = [p["key"] for p in PROGRAMS]
        self.page_prog.refresh()

    def script_path(self, prog):

        override = self.script_override.get(prog["key"])

        if override and Path(override).exists():
            return Path(override)

        candidate = SCRIPT_DIR / prog["script"]

        return candidate if candidate.exists() else None

    def reattach_script(self, key):
        """Point a program row at a different .py file.  Works whether or not
        a file is already attached, so a wrong attachment can be corrected."""

        prog = PROGRAM_BY_KEY[key]

        current = self.script_path(prog)

        start_dir = str(current.parent) if current else str(SCRIPT_DIR)

        path = filedialog.askopenfilename(
            title="Attach a .py file for %s" % prog["name"],
            initialdir=start_dir,
            filetypes=[("Python", "*.py"), ("All Files", "*.*")])

        if not path:
            return

        chosen = Path(path).name

        # A gentle nudge if the file name looks unrelated to this program, but
        # the choice is still honoured - names may differ.
        if chosen.lower() != prog["script"].lower():
            if not messagebox.askyesno(
                    "Attach this file?",
                    "%s normally uses:\n    %s\n\nYou picked:\n    %s\n\n"
                    "Attach it to %s anyway?"
                    % (prog["name"], prog["script"], chosen, prog["name"])):
                return

        self.script_override[key] = path
        self._save_suite_config()
        self.page_prog.refresh()

        self.set_footer("ATTACHED  %s  ->  %s" % (prog["name"], chosen),
                        T.GREEN)

    def reset_script(self, key):
        """Drop a custom attachment and go back to the default file that sits
        next to the launcher (e.g. lock_route_automation_.py)."""

        prog = PROGRAM_BY_KEY[key]

        if key not in self.script_override:
            return

        default = SCRIPT_DIR / prog["script"]

        if messagebox.askyesno(
                "Reset to default",
                "Stop using the custom file and go back to:\n\n    %s\n\n"
                "%s"
                % (prog["script"],
                   "" if default.exists()
                   else "\n(Note: that file is not in the folder yet.)")):

            self.script_override.pop(key, None)
            self._save_suite_config()
            self.page_prog.refresh()

            self.set_footer("RESET  %s  ->  default (%s)"
                            % (prog["name"], prog["script"]), T.SLATE)

    # =====================================================================
    #  EXECUTION
    # =====================================================================

    def start_run(self):

        if self.running:
            return

        if not self.selected:
            messagebox.showwarning("Nothing selected",
                                   "Tick at least one program first.")
            return

        missing = [k for k in self.selected if self.script_path(
            PROGRAM_BY_KEY[k]) is None]

        if missing:
            messagebox.showerror(
                "Script not found",
                "These programs have no script file:\n\n  %s\n\n"
                "Click the row to locate the .py file."
                % "\n  ".join(PROGRAM_BY_KEY[k]["name"] for k in missing))
            return

        # Warn about data files a program expects but which were not loaded.
        gaps = []

        for k in self.selected:
            for need in PROGRAM_BY_KEY[k]["needs"]:
                if not self.files.get(need):
                    label = next(s["label"] for s in DATA_SLOTS
                                 if s["key"] == need)
                    gaps.append("%s  needs  %s" % (PROGRAM_BY_KEY[k]["name"],
                                                   label))

        if gaps:
            proceed = messagebox.askyesno(
                "Data not loaded",
                "These files were not loaded in step 2:\n\n  %s\n\n"
                "Each program can still load its own files from its own "
                "window.\n\nStart the run anyway?" % "\n  ".join(gaps))

            if not proceed:
                return

        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")

        self.session_dir = REPORTS_ROOT / self.oem["code"] / ("SESSION_" + stamp)
        self.session_dir.mkdir(parents=True, exist_ok=True)

        self._write_autofeed_helper()

        self.results = {}
        self.claimed = set()
        self.running = True

        self.show_step(3)
        self.page_run.begin(list(self.selected))

        self._write_session()

        threading.Thread(target=self._run_queue,
                         args=(list(self.selected),), daemon=True).start()

    def _write_autofeed_helper(self):
        """(Re)writes the auto-feed helper next to the launcher so it always
        matches this version.  Silent if it cannot be written - the run then
        falls back to launching programs directly and each program simply
        asks for its files as before."""

        global AUTOFEED_HELPER

        try:
            with open(AUTOFEED_HELPER, "w", encoding="utf-8") as fh:
                fh.write(AUTOFEED_SOURCE)
        except Exception:
            pass

    def _run_queue(self, keys):
        """Runs every selected program one after another.  The next program
        only starts after the current one has closed and its report has been
        collected."""

        self.ui(self.page_run.log, "SESSION FOLDER  %s" % self.session_dir,
                "info")
        self.ui(self.page_run.log,
                "OEM  %s  -  %d PROGRAM(S) QUEUED" % (self.oem["code"],
                                                      len(keys)), "info")

        if AUTOFEED_HELPER.exists():
            if self.unattended:
                self.ui(self.page_run.log,
                        "WALK-AWAY MODE  -  each program is loaded, started, "
                        "and closed automatically. You can leave.", "info")
            else:
                self.ui(self.page_run.log,
                        "ATTENDED MODE  -  files are pre-filled; click START "
                        "inside each program, close it to advance.", "info")

        for position, key in enumerate(keys, start=1):

            if not self.running:
                break

            prog = PROGRAM_BY_KEY[key]
            script = self.script_path(prog)

            self.ui(self.page_run.mark, key, "RUNNING")
            self.ui(self.page_run.set_progress, position - 1, len(keys))
            self.ui(self.page_run.log, "", "plain")
            self.ui(self.page_run.log,
                    "[%d/%d]  STARTING  %s" % (position, len(keys),
                                               prog["name"]), "run")
            self.ui(self.page_run.log, "        %s" % script, "dim")

            if key == "SPL_CASE_CALLING_ON":
                feed = self.files.get("SPL_CASE")
                feed_label = "SPL CASE INPUT"
            else:
                feed = self.files.get("TOC")
                feed_label = "TOC"

            if feed:
                self.ui(self.page_run.log, "        LIST    <- %s  (%s)"
                        % (Path(feed).name, feed_label), "dim")

            if self.files.get("COORDS"):
                self.ui(self.page_run.log, "        COORDS  <- %s"
                        % Path(self.files["COORDS"]).name, "dim")

            if self.files.get("TRACK_COORDS"):
                self.ui(self.page_run.log, "        TRACK COORDS  <- %s"
                        % Path(self.files["TRACK_COORDS"]).name, "dim")

            started = time.time()

            log_handle = None

            try:
                env = os.environ.copy()
                env["EDRC_OEM"] = self.oem["code"]
                env["EDRC_SESSION_DIR"] = str(self.session_dir)
                env["EDRC_PROGRAM"] = key
                env["EDRC_UNATTENDED"] = "1" if self.unattended else "0"

                # Raw slot values, kept for reference / SESSION.json.
                for slot_key, path in self.files.items():
                    if path:
                        env["EDRC_" + slot_key] = str(path)

                # What the auto-feed helper actually hands to the program:
                #   the LIST dialog gets the SPL file for SPL case, else TOC;
                #   the COORDS dialog gets the coordinates file.
                if key == "SPL_CASE_CALLING_ON":
                    list_file = self.files.get("SPL_CASE")
                else:
                    list_file = self.files.get("TOC")

                coords_file = self.files.get("COORDS")
                track_coords_file = self.files.get("TRACK_COORDS")

                if track_coords_file:
                    env["EDRC_TRACK_COORDS"] = str(track_coords_file)
                else:
                    env.pop("EDRC_TRACK_COORDS", None)

                if list_file:
                    env["EDRC_LIST"] = str(list_file)
                else:
                    env.pop("EDRC_LIST", None)

                if coords_file:
                    env["EDRC_COORDS"] = str(coords_file)
                else:
                    env.pop("EDRC_COORDS", None)

                # Tell the helper exactly which buttons to click for THIS
                # program. Visual Inspection has a 4-step driver; all other
                # programs retain their original 3-step drivers.
                drv = PROGRAM_DRIVERS.get(key)
                if drv:
                    env["EDRC_DRIVE_LIST"] = drv[0]
                    if len(drv) == 4:
                        env["EDRC_DRIVE_CONFIG"] = drv[1]
                        env["EDRC_DRIVE_TRACK_COORDS"] = drv[2]
                        env["EDRC_DRIVE_START"] = drv[3]
                        env.pop("EDRC_DRIVE_COORDS", None)
                    else:
                        env["EDRC_DRIVE_COORDS"] = drv[1]
                        env["EDRC_DRIVE_START"] = drv[2]
                        env.pop("EDRC_DRIVE_CONFIG", None)
                        env.pop("EDRC_DRIVE_TRACK_COORDS", None)
                else:
                    for var in ("EDRC_DRIVE_LIST", "EDRC_DRIVE_COORDS",
                                "EDRC_DRIVE_CONFIG",
                                "EDRC_DRIVE_TRACK_COORDS",
                                "EDRC_DRIVE_START"):
                        env.pop(var, None)

                # A per-program folder + console log, created up front so the
                # run leaves an audit trail even for an overnight session.
                prog_folder = self.session_dir / ("%02d_%s" % (position,
                                                               prog["key"]))
                prog_folder.mkdir(parents=True, exist_ok=True)

                try:
                    log_handle = open(prog_folder / "console.log", "w",
                                      encoding="utf-8")
                except Exception:
                    log_handle = None

                self.proc = subprocess.Popen(
                    [sys.executable, str(AUTOFEED_HELPER), str(script)],
                    cwd=str(SCRIPT_DIR), env=env,
                    stdout=log_handle, stderr=subprocess.STDOUT)

                code = self.proc.wait()

            except Exception as exc:

                self.ui(self.page_run.log, "        LAUNCH FAILED  %s" % exc,
                        "fail")
                self.ui(self.page_run.mark, key, "FAILED")
                self.results[key] = {"status": "FAILED", "error": str(exc)}
                continue

            finally:
                self.proc = None
                if log_handle is not None:
                    try:
                        log_handle.close()
                    except Exception:
                        pass

            elapsed = int(time.time() - started)

            reports = self._collect_reports(prog, position, started)

            if not self.running:
                self.ui(self.page_run.mark, key, "STOPPED")
                self.results[key] = {"status": "STOPPED", "reports": reports}
                self.ui(self.page_run.log, "        STOPPED BY OPERATOR",
                        "fail")
                break

            if code == 0 and reports:
                for rep in reports:
                    self.ui(self.page_run.log, "        REPORT  %s"
                            % Path(rep).name, "ok")
                status = "COMPLETE"
            elif code != 0:
                self.ui(self.page_run.log,
                        "        PROGRAM EXITED WITH ERROR CODE %s"
                        % code, "fail")
                status = "FAILED"
            else:
                self.ui(self.page_run.log,
                        "        NO NEW REPORT FOUND FOR THIS PROGRAM", "warn")
                status = "NO REPORT"

            self.ui(self.page_run.log,
                    "        FINISHED  %s  (exit %s, %dm %02ds)"
                    % (prog["name"], code, elapsed // 60, elapsed % 60), "ok")

            self.ui(self.page_run.mark, key, status)

            self.results[key] = {
                "status": status,
                "exit_code": code,
                "seconds": elapsed,
                "reports": reports,
            }

            self.ui(self.page_run.set_progress, position, len(keys))

        self.running = False
        self._write_session()

        self.ui(self.page_run.finish)

    def _collect_reports(self, prog, position, since):
        """Copies any Excel report the program produced into the session
        folder.  Files are matched by the program's own report prefixes, and
        anything newer than the launch time is taken as a fallback."""

        folder = self.session_dir / ("%02d_%s" % (position, prog["key"]))

        found = []
        prefixes = [p.lower() for p in prog["reports"]]

        inputs = {str(Path(p).resolve()).lower()
                  for p in self.files.values() if p}

        try:
            candidates = list(SCRIPT_DIR.glob("*.xlsx"))
        except Exception:
            return found

        fresh = []

        for path in candidates:

            try:
                resolved = str(path.resolve()).lower()

                # Never pick up a data file, and never pick up a report that
                # an earlier program in this session already claimed.
                if resolved in inputs or resolved in self.claimed:
                    continue

                if path.stat().st_mtime < since - 2:
                    continue

                fresh.append(path)

            except Exception:
                continue

        # Prefer files whose name matches this program's own report prefix.
        # If the program was renamed, fall back to any unclaimed new file so
        # a report is collected rather than lost.
        matched = [p for p in fresh
                   if any(p.name.lower().startswith(pref) for pref in prefixes)]

        for path in (matched or fresh):

            try:
                folder.mkdir(parents=True, exist_ok=True)

                target = folder / path.name
                shutil.copy2(path, target)

                self.claimed.add(str(path.resolve()).lower())
                found.append(str(target))

            except Exception:
                continue

        return found

    def stop_run(self):

        if not self.running:
            return

        if not messagebox.askyesno(
                "Stop the run",
                "Stop after closing the program that is running now?\n\n"
                "The remaining programs in the queue will not start."):
            return

        self.running = False

        self.page_run.log("STOP REQUESTED BY OPERATOR", "fail")

        if self.proc and self.proc.poll() is None:
            try:
                self.proc.terminate()
            except Exception:
                pass

    def open_session_folder(self):

        if not self.session_dir or not Path(self.session_dir).exists():
            messagebox.showinfo("Reports", "No session folder yet.")
            return

        try:
            os.startfile(str(self.session_dir))
        except AttributeError:
            subprocess.Popen(["xdg-open", str(self.session_dir)])
        except Exception as exc:
            messagebox.showerror("Reports", str(exc))

    # =====================================================================
    #  PERSISTENCE
    # =====================================================================

    def _write_session(self):

        if not self.session_dir:
            return

        payload = {
            "oem": self.oem["code"] if self.oem else None,
            "created": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "data_files": {k: v for k, v in self.files.items() if v},
            "track_list": self.track_list_path,
            "run_order": [PROGRAM_BY_KEY[k]["name"] for k in self.selected],
            "results": self.results,
        }

        try:
            with open(self.session_dir / "SESSION.json", "w",
                      encoding="utf-8") as fh:
                json.dump(payload, fh, indent=2)
        except Exception:
            pass

    def _load_suite_config(self):

        try:
            if SUITE_CONFIG.exists():
                with open(SUITE_CONFIG, "r", encoding="utf-8") as fh:
                    return json.load(fh)
        except Exception:
            pass

        return {}

    def _save_suite_config(self):

        try:
            with open(SUITE_CONFIG, "w", encoding="utf-8") as fh:
                json.dump(self.script_override, fh, indent=2)
        except Exception:
            pass

    # =====================================================================
    #  THREAD SAFE UI
    # =====================================================================

    def ui(self, fn, *args):
        """Marshals a call from the runner thread onto the tk main loop.

        Tk is not thread safe and calling after() straight from a worker
        thread is unreliable, so the call is parked on a queue that the
        main loop drains in _pump()."""

        self.ui_queue.put((fn, args))

    def _pump(self):
        """Drains anything the runner thread posted, then re-arms itself."""

        while True:
            try:
                fn, args = self.ui_queue.get_nowait()
            except queue.Empty:
                break

            try:
                fn(*args)
            except Exception as exc:
                print("UI update failed:", exc)

        self.after(60, self._pump)

    def on_close(self):

        if self.running:
            if not messagebox.askyesno(
                    "Run in progress",
                    "A program is still running. Close the suite anyway?"):
                return
            self.running = False

        self.destroy()


# =============================================================================
# =============================================================================
#  STEP 1  -  OEM
# =============================================================================
# =============================================================================

class PageOEM(tk.Frame):

    def __init__(self, parent, app):

        super().__init__(parent, bg=T.BG)
        self.app = app

        head = tk.Frame(self, bg=T.BG)
        head.pack(fill="x", padx=40, pady=(34, 6))

        tk.Label(head, text="S T E P   0 1", bg=T.BG, fg=T.BLUE,
                 font=T.f(9, "bold")).pack(anchor="w")

        tk.Label(head, text="Select the interlocking OEM", bg=T.BG,
                 fg=T.TEXT, font=T.f(24, "bold")).pack(anchor="w", pady=(4, 2))

        tk.Label(head,
                 text="The OEM decides how the yard terminal behaves and where "
                      "this session's reports are filed.",
                 bg=T.BG, fg=T.TEXT_SOFT, font=T.f(11)).pack(anchor="w")

        grid = tk.Frame(self, bg=T.BG)
        grid.pack(fill="both", expand=True, padx=40, pady=26)

        for c in range(3):
            grid.columnconfigure(c, weight=1, uniform="oem")
        for r in range(2):
            grid.rowconfigure(r, weight=1, uniform="oem")

        for i, oem in enumerate(OEMS):
            self._card(grid, oem).grid(row=i // 3, column=i % 3,
                                       padx=12, pady=12, sticky="nsew")

    def _card(self, parent, oem):

        holder = tk.Frame(parent, bg=T.CARD, highlightthickness=1,
                          highlightbackground=T.CARD_EDGE, cursor="hand2")

        stripe = tk.Frame(holder, bg=oem["accent"], height=6)
        stripe.pack(fill="x")

        inner = tk.Frame(holder, bg=T.CARD)
        inner.pack(fill="both", expand=True, padx=26, pady=22)

        # OEM logo
        # All six logos use the same visual bounding box.  Extra transparent
        # / white canvas around a source image is trimmed first so logos such
        # as HITACHI, NIPPON and KYOSAN do not appear artificially smaller.
        logo_holder = tk.Frame(inner, bg=T.CARD, height=82)
        logo_holder.pack(fill="x", pady=(0, 2))
        logo_holder.pack_propagate(False)
        logo_photo = None
        logo_lab = None
        if PIL_OK:
            try:
                import base64 as _b64
                from io import BytesIO
                raw = _b64.b64decode(OEM_LOGO_DATA.get(oem["code"], ""))
                img = Image.open(BytesIO(raw)).convert("RGBA")

                # Trim transparent margins.
                alpha = img.getchannel("A")
                alpha_bbox = alpha.getbbox()
                if alpha_bbox:
                    img = img.crop(alpha_bbox)

                # Trim white margins for logos supplied on white backgrounds.
                px = img.load()
                w, h = img.size
                xs, ys = [], []
                for yy in range(h):
                    for xx in range(w):
                        r, g, b, a = px[xx, yy]
                        if a > 10 and not (r >= 245 and g >= 245 and b >= 245):
                            xs.append(xx)
                            ys.append(yy)
                if xs and ys:
                    pad = 3
                    left = max(0, min(xs) - pad)
                    top = max(0, min(ys) - pad)
                    right = min(w, max(xs) + 1 + pad)
                    bottom = min(h, max(ys) + 1 + pad)
                    img = img.crop((left, top, right, bottom))

                # Same maximum visual size for every OEM, preserving each
                # logo's original aspect ratio.
                img.thumbnail((300, 68), Image.Resampling.LANCZOS)
                logo_photo = ImageTk.PhotoImage(img)
                logo_lab = tk.Label(logo_holder, image=logo_photo, bg=T.CARD,
                                    bd=0, highlightthickness=0)
                logo_lab.image = logo_photo
                logo_lab.pack(anchor="w", pady=0)
            except Exception:
                logo_photo = None

        # Company description is placed directly below the logo.
        note = tk.Label(inner, text=oem["note"], bg=T.CARD, fg=T.TEXT_SOFT,
                        font=T.f(11))
        note.pack(anchor="w", pady=(0, 0))

        tk.Frame(inner, bg=T.CARD).pack(fill="both", expand=True)

        go = tk.Label(inner, text="OPEN  >", bg=T.CARD, fg=oem["accent"],
                      font=T.f(10, "bold"))
        go.pack(anchor="w")

        widgets = [holder, inner, note, go, stripe, logo_holder]
        if logo_lab is not None:
            widgets.append(logo_lab)

        def enter(_=None):
            holder.config(highlightbackground=oem["accent"],
                          highlightthickness=2)
            go.config(text="OPEN  >>")

        def leave(_=None):
            holder.config(highlightbackground=T.CARD_EDGE,
                          highlightthickness=1)
            go.config(text="OPEN  >")

        def choose(_=None):
            self.app.oem = oem
            self.app.oem_badge.config(
                text="  //  %s" % oem["code"], fg=oem["accent"])
            self.app.set_footer("OEM  %s  SELECTED" % oem["code"],
                                oem["accent"])
            self.app.show_step(1)

        for w in widgets:
            w.bind("<Enter>", enter)
            w.bind("<Leave>", leave)
            w.bind("<Button-1>", choose)
            try:
                w.config(cursor="hand2")
            except Exception:
                pass

        return holder

    def on_show(self):
        self.app.set_footer("READY  -  SELECT AN OEM TO BEGIN")


