# This is intentionally separate from visual_inspection_tracks.py.  The
# TRACK CAPTURE button in STEP 2 must NOT open the Visual Inspection dashboard.
# It starts only the track-list/coordinate-capture UI.
DIRECT_TRACK_CAPTURE_SOURCE = r'''
import os
import ctypes
import tkinter as tk
from tkinter import messagebox
from pathlib import Path
from openpyxl import Workbook, load_workbook
from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
from openpyxl.utils import get_column_letter
from pynput import keyboard as pynput_keyboard

TRACK_LIST_FILE = os.environ.get("EDRC_TRACK_LIST", "")
COORD_FILE = os.environ.get(
    "EDRC_TRACK_COORDS",
    str(Path.home() / "Desktop" / "TRACK_COORDINATES_CAPTURED.xlsx")
)

tracks = []
track_points = {}
track_index = 0
undo_stack = []
listener = None
overlay = None
progress = None
track_label = None
status = None

def load_track_list():
    global tracks, track_points
    if not TRACK_LIST_FILE or not os.path.exists(TRACK_LIST_FILE):
        raise FileNotFoundError("Track list Excel not found: " + TRACK_LIST_FILE)

    wb = load_workbook(TRACK_LIST_FILE, data_only=True)
    ws = wb.active
    headers = {"TRACK", "TRACK NAME", "TRACK_NAME", "TRACKS"}
    col = 1
    start = 1
    first = next(ws.iter_rows(min_row=1, max_row=1, values_only=True), None)
    if first:
        for i, value in enumerate(first, start=1):
            if value is not None and str(value).strip().upper() in headers:
                col, start = i, 2
                break

    seen = set()
    result = []
    for row in ws.iter_rows(min_row=start, values_only=True):
        if not row or len(row) < col or row[col - 1] is None:
            continue
        name = str(row[col - 1]).replace(".0", "").strip().upper()
        if name and name not in seen:
            seen.add(name)
            result.append(name)
    wb.close()
    if not result:
        raise ValueError("No track names were found in the selected Excel file.")
    tracks = result
    track_points = {t: () for t in tracks}

def create_excel():
    wb = Workbook()
    ws = wb.active
    ws.title = "TRACK COORDINATES"
    ws.merge_cells("A1:C1")
    ws["A1"] = "TRACK COORDINATES"
    ws["A1"].font = Font(bold=True, size=16, color="FFFFFF")
    ws["A1"].fill = PatternFill("solid", fgColor="1E293B")
    ws["A1"].alignment = Alignment(horizontal="center")
    ws.append([])
    ws.append(["TRACK NAME", "X COORDINATE", "Y COORDINATE"])
    fill = PatternFill("solid", fgColor="2563EB")
    thin = Side(style="thin", color="000000")
    border = Border(left=thin, right=thin, top=thin, bottom=thin)
    for cell in ws[3]:
        cell.font = Font(bold=True, color="FFFFFF")
        cell.fill = fill
        cell.border = border
        cell.alignment = Alignment(horizontal="center")
    Path(COORD_FILE).parent.mkdir(parents=True, exist_ok=True)
    wb.save(COORD_FILE)
    wb.close()

def save_coordinate(track, x, y):
    if not os.path.exists(COORD_FILE):
        create_excel()
    wb = load_workbook(COORD_FILE)
    ws = wb.active
    row_found = None
    for row in range(4, ws.max_row + 1):
        value = ws.cell(row=row, column=1).value
        if value is not None and str(value).strip().upper() == track.upper():
            row_found = row
            break
    row = row_found or (ws.max_row + 1)
    ws.cell(row=row, column=1).value = track
    ws.cell(row=row, column=2).value = int(x)
    ws.cell(row=row, column=3).value = int(y)
    thin = Side(style="thin", color="000000")
    border = Border(left=thin, right=thin, top=thin, bottom=thin)
    for cell in ws[row]:
        cell.border = border
        cell.alignment = Alignment(horizontal="center")
    for column in ws.columns:
        max_len = max((len(str(c.value)) for c in column if c.value is not None), default=0)
        ws.column_dimensions[get_column_letter(column[0].column)].width = max_len + 5
    wb.save(COORD_FILE)
    wb.close()

def refresh():
    if track_index >= len(tracks):
        return
    progress.config(text=f"TRACK {track_index + 1} of {len(tracks)}")
    track_label.config(text=tracks[track_index])
    status.config(text="Move the mouse onto the track\
\
Press SPACE to save\
Press BACKSPACE to undo")
    overlay.lift()

def save_current_point():
    global track_index
    if track_index >= len(tracks):
        return
    user32 = ctypes.windll.user32
    pt = ctypes.wintypes.POINT()
    user32.GetCursorPos(ctypes.byref(pt))
    track = tracks[track_index]
    old = track_points.get(track)
    undo_stack.append((track_index, track, list(old) if isinstance(old, (list, tuple)) and len(old) == 2 else None))
    track_points[track] = [pt.x, pt.y]
    save_coordinate(track, pt.x, pt.y)
    track_index += 1
    if track_index >= len(tracks):
        finish()
    else:
        refresh()

def undo():
    global track_index
    if not undo_stack:
        return
    old_index, track, old_value = undo_stack.pop()
    track_index = old_index
    if old_value is None:
        track_points[track] = ()
    else:
        track_points[track] = old_value
    refresh()

def finish():
    global listener
    if listener:
        listener.stop()
        listener = None
    try:
        overlay.destroy()
    except Exception:
        pass
    messagebox.showinfo("TRACK CAPTURE", f"All {len(tracks)} track coordinates captured.\
\
Saved to:\
{COORD_FILE}")
    root.destroy()

def cancel():
    global listener
    if listener:
        listener.stop()
        listener = None
    try:
        overlay.destroy()
    except Exception:
        pass
    root.destroy()

def on_key(key):
    if key == pynput_keyboard.Key.space:
        root.after(0, save_current_point)
    elif key == pynput_keyboard.Key.backspace:
        root.after(0, undo)

root = tk.Tk()
root.withdraw()
root.title("EDRC Track Capture")

try:
    load_track_list()
except Exception as exc:
    messagebox.showerror("TRACK LIST ERROR", str(exc))
    root.destroy()
    raise SystemExit(1)

if not os.path.exists(COORD_FILE):
    create_excel()

overlay = tk.Toplevel(root)
overlay.title("Coordinate Capture Guide")
overlay.configure(bg="#0f172a")
overlay.resizable(False, False)
overlay.attributes("-topmost", True)
screen_w = overlay.winfo_screenwidth()
overlay.geometry(f"420x320+{screen_w - 440}+40")
overlay.protocol("WM_DELETE_WINDOW", cancel)
overlay.bind("<space>", lambda e: "break")
overlay.bind("<Return>", lambda e: "break")

tk.Label(overlay, text="COORDINATE CAPTURE", font=("Segoe UI", 11, "bold"), bg="#0f172a", fg="#64748b").pack(pady=(16, 0))
progress = tk.Label(overlay, text="", font=("Segoe UI", 10), bg="#0f172a", fg="#94a3b8")
progress.pack(pady=(2, 10))
track_label = tk.Label(overlay, text="", font=("Segoe UI", 18, "bold"), bg="#0f172a", fg="#a855f7")
track_label.pack()
tk.Label(overlay, text="CAPTURE COORDINATE", font=("Segoe UI", 15, "bold"), bg="#0f172a", fg="#22c55e").pack(pady=(6, 8))
status = tk.Label(overlay, text="", font=("Segoe UI", 10), bg="#0f172a", fg="#cbd5e1", wraplength=380, justify="center")
status.pack(pady=(0, 10))

tk.Button(overlay, text="UNDO LAST CLICK", command=undo, bg="#f59e0b", fg="#1a1a1a", relief="flat", cursor="hand2", font=("Segoe UI", 10, "bold"), width=22).pack(pady=(10, 2))
tk.Label(overlay, text="(or press BACKSPACE)", font=("Segoe UI", 8), bg="#0f172a", fg="#475569").pack()
tk.Button(overlay, text="CANCEL CAPTURE", command=cancel, bg="#0f172a", fg="#64748b", activeforeground="#ef4444", relief="flat", cursor="hand2", font=("Segoe UI", 9, "underline"), takefocus=0).pack(side="bottom", pady=(0, 10))

listener = pynput_keyboard.Listener(on_press=on_key)
listener.daemon = True
listener.start()
refresh()
root.mainloop()
'''

class PageData(tk.Frame):

    def __init__(self, parent, app):

        super().__init__(parent, bg=T.BG)
        self.app = app
        self.rows = {}

        head = tk.Frame(self, bg=T.BG)
        head.pack(fill="x", padx=40, pady=(30, 6))

        tk.Label(head, text="S T E P   0 2", bg=T.BG, fg=T.BLUE,
                 font=T.f(9, "bold")).pack(anchor="w")

        self.title_lab = tk.Label(head, text="Load the yard data", bg=T.BG,
                                  fg=T.TEXT, font=T.f(24, "bold"))
        self.title_lab.pack(anchor="w", pady=(4, 2))

        tk.Label(head,
                 text="Load each file once here and every program in the run "
                      "receives it.",
                 bg=T.BG, fg=T.TEXT_SOFT, font=T.f(11)).pack(anchor="w")

        # ---- scrollable list of data slots ----
        body = tk.Frame(self, bg=T.BG)
        body.pack(fill="both", expand=True, padx=40, pady=(20, 6))

        canvas = tk.Canvas(body, bg=T.BG, highlightthickness=0, bd=0)
        scroll = tk.Scrollbar(body, orient="vertical", command=canvas.yview)
        holder = tk.Frame(canvas, bg=T.BG)

        holder.bind("<Configure>", lambda e: canvas.configure(
            scrollregion=canvas.bbox("all")))

        window = canvas.create_window((0, 0), window=holder, anchor="nw")
        canvas.bind("<Configure>",
                    lambda e: canvas.itemconfig(window, width=e.width))
        canvas.configure(yscrollcommand=scroll.set)

        canvas.pack(side="left", fill="both", expand=True)
        scroll.pack(side="right", fill="y")

        canvas.bind_all("<MouseWheel>", lambda e: canvas.yview_scroll(
            int(-e.delta / 120), "units") if self.winfo_ismapped() else None)

        for slot in DATA_SLOTS:
            self._slot_row(holder, slot)

        # ---- footer nav ----
        nav = tk.Frame(self, bg=T.BG)
        nav.pack(fill="x", padx=40, pady=(6, 26))

        GhostButton(nav, "<  BACK", lambda: self.app.show_step(0),
                    w=150).pack(side="left")

        self.ready_lab = tk.Label(nav, text="", bg=T.BG, fg=T.TEXT_SOFT,
                                  font=T.f(10, "bold"))
        self.ready_lab.pack(side="left", padx=18)

        RButton(nav, "NEXT  >", lambda: self.app.show_step(2),
                w=190, face=T.BLUE).pack(side="right")

    # ------------------------------------------------------------------

    def _slot_row(self, parent, slot):

        row = card(parent)
        row.pack(fill="x", pady=7)

        inner = tk.Frame(row, bg=T.CARD)
        inner.pack(fill="x", padx=22, pady=16)

        # left : lamp + text
        left = tk.Frame(inner, bg=T.CARD)
        left.pack(side="left", fill="x", expand=True)

        top = tk.Frame(left, bg=T.CARD)
        top.pack(anchor="w")

        lamp = Lamp(top, d=13, colour=T.GREY, bg=T.CARD)
        lamp.pack(side="left", pady=(1, 0))

        tk.Label(top, text=slot["label"], bg=T.CARD, fg=T.TEXT,
                 font=T.f(13, "bold")).pack(side="left", padx=8)

        tk.Label(left, text=slot["hint"], bg=T.CARD, fg=T.TEXT_SOFT,
                 font=T.f(10), justify="left", wraplength=620).pack(
                     anchor="w", pady=(4, 0))

        status = tk.Label(left, text="Not loaded", bg=T.CARD, fg=T.TEXT_SOFT,
                          font=T.mono(9))
        status.pack(anchor="w", pady=(6, 0))

        track_list_status = None
        if slot["key"] == "TRACK_COORDS":
            track_list_status = tk.Label(
                left, text="Track list: Not selected", bg=T.CARD,
                fg=T.TEXT_SOFT, font=T.mono(9))
            track_list_status.pack(anchor="w", pady=(3, 0))

        self.rows[slot["key"]] = (lamp, status, track_list_status)

        # right : action buttons
        right = tk.Frame(inner, bg=T.CARD)
        right.pack(side="right")

        if slot["key"] == "TRACK_COORDS":

            # Track coordinates have their own two-stage workflow:
            # TRACK LIST -> TRACK CAPTURE.  BROWSE remains available for an
            # already-captured workbook.
            RButton(right, "TRACK LIST", self.app.pick_track_list,
                    w=116, h=42, face=T.VIOLET, bg=T.CARD,
                    font=T.f(9, "bold")).pack(side="left", padx=(0, 8))

            RButton(right, "TRACK CAPTURE", self.app.start_track_capture,
                    w=132, h=42, face=T.VIOLET, bg=T.CARD,
                    font=T.f(9, "bold")).pack(side="left", padx=(0, 8))

            RButton(right, "BROWSE",
                    lambda k=slot["key"], l=slot["label"]:
                        self.app.pick_file(k, l),
                    w=112, h=42, face=T.BLUE, bg=T.CARD,
                    font=T.f(9, "bold")).pack(side="left")

        elif slot["recorder"]:

            pair = tk.Frame(right, bg=T.CARD)
            pair.pack(side="left")

            RButton(pair, "NEW", self.app.record_new_coordinates,
                    w=104, h=42, face=T.VIOLET, bg=T.CARD,
                    font=T.f(10, "bold")).pack(side="left", padx=(0, 8))

            RButton(pair, "EXISTING",
                    lambda k=slot["key"], l=slot["label"]:
                        self.app.pick_file(k, l),
                    w=124, h=42, face=T.BLUE, bg=T.CARD,
                    font=T.f(10, "bold")).pack(side="left")

        else:

            RButton(right, "BROWSE",
                    lambda k=slot["key"], l=slot["label"]:
                        self.app.pick_file(k, l),
                    w=140, h=42, face=T.BLUE, bg=T.CARD,
                    font=T.f(10, "bold")).pack(side="left")

        clear = GhostButton(right, "CLEAR",
                            lambda k=slot["key"]: self.app.clear_file(k),
                            w=96, h=42, colour=T.TEXT_SOFT)
        clear.configure(bg=T.CARD)
        clear.itemconfig(clear.shape, fill=T.CARD)
        clear.base_bg = T.CARD
        clear.pack(side="left", padx=(8, 0))

    # ------------------------------------------------------------------

    def refresh(self):

        for slot in DATA_SLOTS:

            row_widgets = self.rows[slot["key"]]
            lamp, status = row_widgets[0], row_widgets[1]
            track_list_status = row_widgets[2] if len(row_widgets) > 2 else None
            path = self.app.files.get(slot["key"])

            if path:
                lamp.set(T.GREEN)
                status.config(text=short_path(path), fg=T.GREEN)
            else:
                lamp.set(T.GREY, lit=False)
                status.config(text="Not loaded", fg=T.TEXT_SOFT)

            if track_list_status is not None:
                track_path = self.app.track_list_path
                if track_path:
                    track_list_status.config(
                        text="Track list: " + short_path(track_path),
                        fg=T.VIOLET)
                else:
                    track_list_status.config(
                        text="Track list: Not selected",
                        fg=T.TEXT_SOFT)

        loaded = []

        if self.app.files.get("TOC"):
            loaded.append("TOC")
        if self.app.files.get("COORDS"):
            loaded.append("coordinates")
        if self.app.files.get("SPL_CASE"):
            loaded.append("SPL case")
        if self.app.files.get("TRACK_COORDS"):
            loaded.append("track coordinates")
        if self.app.track_list_path:
            loaded.append("track list")

        if not self.app.files.get("TOC"):
            self.ready_lab.config(text="Load the TOC to run any program",
                                  fg=T.TEXT_SOFT)
        else:
            self.ready_lab.config(
                text="Loaded: " + ", ".join(loaded),
                fg=T.GREEN)

    def on_show(self):

        if self.app.oem:
            self.title_lab.config(
                text="Load the yard data  -  %s" % self.app.oem["code"])

        self.refresh()
        self.app.set_footer("STEP 2  -  LOAD THE DATA FILES")


